with h5py.File(OUTPUT_H5, "w") as h5:
    h5.attrs["# groups"] = NUM_GROUPS
    material_group = h5.create_group("material")
    for material_name, data in materials.items():
        group = material_group.create_group(material_name)
        for dataset_name, values in data.items():
            group.create_dataset(dataset_name, data=values)

print(f"Wrote OpenMOC material library: {OUTPUT_H5}")
